std::optional<std::span<const unsigned char>> asset_bytes(std::string_view key) {
    for (const auto& e : kAssets) {
        if (e.key == key) {
            return std::span<const unsigned char>(e.data, e.size);
        }
    }
    return std::nullopt;
}

